/*
 * The rest of the giants' moons, 414 of them: drawn where they are and
 * turning, but never picked, named or traced. Each goes round an ellipse
 * fitted to JPL Horizons as kepler.ts's are, over 1950 to 2100 or the years
 * Horizons has. The far ones, which the Sun's pull swings about more than an
 * ellipse can follow, are off by a sixth of their distance from the planet at
 * the median and four fifths at the worst; the close ones by under 6,000 km,
 * Polydeuces by 18,000. The newest, S/2025 U 1, is on the catalogue's
 * ellipse, and S/2023 S 38 is fitted over the ten years round now. How bright
 * each is and how big come from Wikipedia's lists of each planet's moons, and
 * how fast 34 of them turn from their lightcurves (Luu, Denk and Mottola,
 * Farkas-Takács, Gomes-Júnior and others). The close ones keep one face to
 * their planet. The rest is made up, each moon's own and the same every time:
 * which way the others' poles point and where their turn starts, how fast the
 * unmeasured ones turn, and their shapes but for Larissa's and the sizes of
 * the 16 measured (shapes.ts).
 */

import { presenceOf, yearsOf } from './deep'
import { locked, toEcliptic, turnedTo } from './ephemeris'
import type { Vec3 } from './ephemeris'
import { ellipse, plane } from './kepler'
import type { Row } from './kepler'

export type Giant = 'jupiter' | 'saturn' | 'uranus' | 'neptune'

/** One of them, as drawn. */
export interface CrowdMoon {
  name: string
  parent: Giant
  /** Absolute magnitude: how bright it is full on, an AU from both the Sun and the eye. */
  H: number
  /** Mean radius, km. */
  radius: number
  row: Row
  plane: number[]
  swing?: (t: number) => number
  /** Keeps one face to its planet. */
  locked: boolean
  /** If not, its pole on the J2000 equator, its prime meridian's angle at J2000, and its degrees a day. */
  pole: { x: number; y: number; z: number }
  w: number
  rate: number
  color: string
  /** The flat map it is painted with, one to each family. */
  map: string
  /** Years from J2000 it is surest at, years either side it holds there, and years in which it then drifts a radian. */
  smear: [mid: number, grace: number, drift: number]
  /** Its sizes along three axes, km, where measured. */
  dims: [number, number, number] | null
  /** 0 to 1, its own: which of the made-up shapes it takes. */
  look: number
}

/**
 * Each family's colour: the close ones as the named moons beside them,
 * Jupiter's far ones grey as Himalia, Saturn's that go round backward dark as
 * Phoebe and those that go forward redder, Uranus's red as Sycorax, and
 * Neptune's grey.
 */
export const CROWD_COLOURS: Record<string, string> = {
  'crowd-saturn-close': '#d5d5d3',
  'crowd-uranus-close': '#6a6967',
  'crowd-neptune-close': '#6f6b67',
  'crowd-jupiter-far': '#77736e',
  'crowd-saturn-far': '#574a40',
  'crowd-saturn-back': '#4a4440',
  'crowd-uranus-far': '#66544a',
  'crowd-neptune-far': '#5f5b57',
}

