/** Sizes along three axes, km, where Voyager 2 or Cassini measured them (Wikipedia's lists). */
const DIMS: Record<string, [number, number, number]> = {
  Methone: [4, 2.6, 2.4],
  Polydeuces: [3.5, 3.1, 2.7],
  Pallene: [5.8, 4.2, 3.7],
  Aegaeon: [1.4, 0.5, 0.4],
  Cordelia: [50, 36, 36],
  Ophelia: [54, 38, 38],
  Bianca: [64, 46, 46],
  Cressida: [92, 74, 74],
  Desdemona: [90, 54, 54],
  Juliet: [150, 74, 74],
  Portia: [156, 126, 126],
  Belinda: [128, 64, 64],
  Naiad: [96, 60, 52],
  Thalassa: [108, 100, 52],
  Despina: [180, 148, 128],
  Galatea: [204, 184, 144],
  Larissa: [216, 204, 168],
}

/**
 * What the ellipses leave out, added to M, degrees, `t` days from J2000:
 * Methone, Anthe and Aegaeon keep in step with Mimas, which Tethys swings to
 * and fro every 71 years, and each rocks about its place in that step;
 * Polydeuces rocks about its place behind Dione.
 */
const SWING: Record<string, (t: number) => number> = {
  Methone: (t) => 40.51225 * Math.sin((2 * Math.PI * (t + 10082.25)) / 25797.83) + 4.782499 * Math.sin((2 * Math.PI * (t + 146.6529)) / 519.9115),
  Polydeuces: (t) => 25.90066 * Math.sin((2 * Math.PI * (t - 83.43559)) / 791.7328) + 2.564453 * Math.sin((2 * Math.PI * (t - 182.1177)) / 395.869),
  Anthe: (t) => 39.52428 * Math.sin((2 * Math.PI * (t + 10061)) / 25755.95) + 7.082475 * Math.sin((2 * Math.PI * (t - 174.0322)) / 761.0511),
  Aegaeon: (t) => 50.75572 * Math.sin((2 * Math.PI * (t + 10064.52)) / 25763.56) + 2.109752 * Math.sin((2 * Math.PI * (t - 86.61499)) / 1274.989),
}

/** Where not the ellipses' [0, 1000, 3000], as deep.ts has them: Uranus's close moons jostle each other, and the two found last are known only round now. */
const SMEAR: Record<string, [number, number, number]> = {
  'S/2023 S 38': [25, 5, 3],
  'S/2025 U 1': [25, 0, 2],
}

/** Numbers 0 to 1 of a name's own, the same every time: its FNV-1a hash, fed to mulberry32. */
export function seeded(name: string): () => number {
  let h = 2_166_136_261
  for (let i = 0; i < name.length; i++) h = Math.imul(h ^ name.charCodeAt(i), 16_777_619)
  let a = h >>> 0
  return () => {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296
  }
}

export const CROWD: CrowdMoon[] = TABLE.map(([name, parent, H, diameter, hours, row]) => {
  const next = seeded(name)
  const z = 2 * next() - 1
  const round = 2 * Math.PI * next()
  const w = 360 * next()
  const guess = 5 + 15 * next()
  const look = next()
  const close = row[0] < 2e6
  const map = 'crowd-' + (close ? parent + '-close' : parent === 'saturn' && row[10] < 0 ? 'saturn-back' : parent + '-far')
  const h = Math.sqrt(1 - z * z)
  return {
    name,
    parent,
    H,
    radius: diameter / 2,
    row,
    plane: plane(row[9], row[10]),
    swing: SWING[name],
    locked: hours === 0,
    pole: { x: h * Math.cos(round), y: h * Math.sin(round), z },
    w,
    rate: (360 * 24) / (hours || guess),
    color: CROWD_COLOURS[map],
    map,
    smear: SMEAR[name] ?? [0, 1000, close && parent === 'uranus' ? 600 : 3000],
    dims: DIMS[name] ?? null,
    look,
  }
})

/** Julian day of J2000. */
const J2000 = 2_451_545

/** A moon `tt` days from J2000: km from its planet's centre, on the ecliptic. */
export function crowdAt(c: CrowdMoon, tt: number): Vec3 {
  return toEcliptic(...ellipse(c.row, c.plane, tt + J2000, c.swing))
}

/** Its own axes, as posesAt's: `at` is where it is from its planet. */
export function crowdAxes(c: CrowdMoon, tt: number, at: Vec3): [Vec3, Vec3, Vec3] {
  if (!c.locked) return turnedTo(c.pole, c.w + ((c.rate * tt) % 360))
  const n = crowdAt(c, tt + 1e-3)
  return locked(at, [n[0] - at[0], n[1] - at[1], n[2] - at[2]])
}

/** How much of it is still at its place, as presenceOf has it. */
export function crowdPresence(c: CrowdMoon, ms: number): number {
  const [mid, grace, drift] = c.smear
  return presenceOf(Math.min(100, (Math.max(0, Math.abs(yearsOf(ms) - mid) - grace) / drift) ** 2))
}
